import test from 'node:test';import assert from 'node:assert/strict';
import {puzzleStep,puzzleChoices,decodePuzzleAnswer,patternCatalogue} from '../wayglass-puzzle.js';
import {SCHOOLS,schoolMatches,withDoctrines} from '../constellation-model.js';
import {CORES,SUPPORTS,defaultHero,compileTechnique} from '../mako.js';
import {starFibres,fibreAudit,puzzleAssignments} from '../kakeya-math.js';
test('all three puzzle grammars produce exact full directional coverage',()=>{for(const n of [2,3,4]){const assignments=puzzleAssignments(n);for(let route=1;route<2**n;route++){let step=puzzleStep(n,route);assert.ok(puzzleChoices(step,n).includes(step.answer));if(step.total===2){assert.equal(decodePuzzleAnswer(step,step.answer),null);step=puzzleStep(n,route,1);}assert.equal(decodePuzzleAnswer(step,step.answer),route);assignments[route-1]=decodePuzzleAnswer(step,step.answer);}const a=fibreAudit(starFibres(n,assignments),n);assert.equal(a.covered,2**n-1);assert.equal(a.weight,3*2**n-2);}});
test('wrong choices never decode to a completed route, including bridge and echo phases',()=>{for(const n of [2,3,4])for(let r=1;r<2**n;r++)for(const phase of [0,1]){const step=puzzleStep(n,r,phase);for(const choice of puzzleChoices(step,n).filter(d=>d!==step.answer))assert.notEqual(decodePuzzleAnswer(step,choice),r);}});
test('every core and support preview uses the real recipe compiler without granting ownership',()=>{const s={party:[0],cores:['earth'],supports:['focus'],heroes:[defaultHero(0)]},before=JSON.stringify(s);for(const support of SUPPORTS){const rows=patternCatalogue(s,support.id);assert.equal(rows.length,CORES.length);for(const row of rows){assert.deepEqual(row.technique,withDoctrines(s.heroes[0],compileTechnique(row.id,support.id,{character:0,ap:s.heroes[0].ap?.[row.id]||0})));assert.deepEqual(row.schools,SCHOOLS.filter(x=>schoolMatches(x,{core:row.id,support:support.id})));assert.equal(row.capacity,3);assert.equal(row.known,row.id==='earth');}}assert.equal(JSON.stringify(s),before);});

test('equipped school forks are reflected in preview without granting nodes',()=>{const h=defaultHero(0);h.doctrineBuild=[{id:'stone',root:true,surge:true,cap:true}];const s={party:[0],heroes:[h],cores:['earth'],supports:['focus']};const p=patternCatalogue(s).find(x=>x.id==='earth'),base=compileTechnique('earth','focus',{character:0,ap:0});assert.ok(p.technique.power>base.power);assert.equal(p.technique.cost,base.cost+1);assert.equal(p.technique.doctrines[0].id,'stone');assert.equal(s.skillGrid,undefined);});
